//! Self-recovery v3 tests (18-word paper phrase + server half U).
//!
//! - The word list equals bitcoin/bips `bip-0039/english.txt` (SHA-256).
//! - Standard BIP39 18-word encoding (known vectors), round trip, bad checksum, bad word, wrong word count, wrong U,
//!   another account's public key, version byte.
//! - Cross-implementation vectors: `tests/vectors/self-recovery-rust.json` is generated by this file from fixed seeds
//!   and opened by the JavaScript reference implementation; `tests/vectors/self-recovery-dev.json` is generated by the
//!   JavaScript reference implementation and opened here.
//!   To regenerate the Rust file: `GORI_WRITE_VECTORS=1 cargo test --test self_recovery`
//! - C boundary (ffi): round trip, NULL output pointers, phrase that is not UTF-8.
//! - Post-quantum version: backup version 4 (the two 32-byte values are seeds), version 3 (old format) is `StaleKey`,
//!   and after recovery the HEK and the ML-DSA binding are unchanged.

use std::path::PathBuf;

use gori_core::core::{BACKUP_LEN, BACKUP_V1, BACKUP_V3, BACKUP_V4, LOCATOR_LEN};
use gori_core::crypto::NONCE_LEN;
use gori_core::ffi::{self, GoriBuf};
use gori_core::phrase::{self, ENTROPY_LEN, PHRASE_WORDS};
use gori_core::{bip39_en, crypto, Core, Error, Slot};
use rand_chacha::rand_core::{CryptoRng, Error as RandError, RngCore, SeedableRng};
use rand_chacha::ChaCha20Rng;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

/// SHA-256 of bitcoin/bips bip-0039/english.txt (one word per line, trailing newline)
const ENGLISH_TXT_SHA256: &str = "2f5eed53a4727b4bf8880d8f3f199efc90e58503646d9ff8eff3a2ed3b24dbda";

fn h(s: &str) -> Vec<u8> {
    hex::decode(s).unwrap_or_else(|_| panic!("hex: {s}"))
}

fn x(b: &[u8]) -> String {
    hex::encode(b)
}

fn seeded(seed: u64) -> Core {
    Core::with_rng(Box::new(ChaCha20Rng::seed_from_u64(seed)))
}

/// RNG that returns preset bytes in order, to replay the R, U and nonce used by another implementation (the JavaScript
/// reference implementation). Panics when the preset bytes run out.
struct Replay(Vec<u8>);

impl RngCore for Replay {
    fn next_u32(&mut self) -> u32 {
        let mut b = [0u8; 4];
        self.fill_bytes(&mut b);
        u32::from_le_bytes(b)
    }
    fn next_u64(&mut self) -> u64 {
        let mut b = [0u8; 8];
        self.fill_bytes(&mut b);
        u64::from_le_bytes(b)
    }
    fn fill_bytes(&mut self, dest: &mut [u8]) {
        assert!(self.0.len() >= dest.len(), "Replay: more random bytes requested than were preset");
        let rest = self.0.split_off(dest.len());
        dest.copy_from_slice(&self.0);
        self.0 = rest;
    }
    fn try_fill_bytes(&mut self, dest: &mut [u8]) -> Result<(), RandError> {
        self.fill_bytes(dest);
        Ok(())
    }
}

impl CryptoRng for Replay {}

/// Core with the account and encryption keys loaded
fn with_keys(core: Core, account: &[u8], enc: &[u8]) -> Core {
    let mut c = core;
    c.load(Slot::Account, account).unwrap();
    c.load(Slot::Enc, enc).unwrap();
    c
}

fn keys(seed: u64) -> ([u8; 32], [u8; 32]) {
    let mut r = ChaCha20Rng::seed_from_u64(seed);
    let (mut a, mut e) = ([0u8; 32], [0u8; 32]);
    r.fill_bytes(&mut a);
    r.fill_bytes(&mut e);
    (a, e)
}

// ── Word list ──

#[test]
fn word_list_is_bip39_english() {
    let mut text = bip39_en::WORDS.join("\n");
    text.push('\n');
    assert_eq!(x(&Sha256::digest(text.as_bytes())), ENGLISH_TXT_SHA256, "src/bip39_en.rs differs from english.txt");
    assert_eq!(bip39_en::WORDS.len(), 2048);
    assert!(bip39_en::WORDS.windows(2).all(|w| w[0] < w[1]), "sorted, no duplicates");
    assert!(bip39_en::WORDS
        .iter()
        .all(|w| (3..=bip39_en::MAX_WORD_LEN).contains(&w.len()) && w.bytes().all(|b| b.is_ascii_lowercase())));
    let mut prefixes: Vec<&str> = bip39_en::WORDS.iter().map(|w| &w[..w.len().min(4)]).collect();
    prefixes.dedup();
    assert_eq!(prefixes.len(), 2048, "the first four letters identify each word");
}

// ── Encoding ──

/// Standard BIP39 18-word vectors (the 192-bit entries of Trezor python-mnemonic vectors.json), cross-checked independently
const KNOWN: &[(&str, &str)] = &[
    (
        "000000000000000000000000000000000000000000000000",
        "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon agent",
    ),
    (
        "7f7f7f7f7f7f7f7f7f7f7f7f7f7f7f7f7f7f7f7f7f7f7f7f",
        "legal winner thank year wave sausage worth useful legal winner thank year wave sausage worth useful legal will",
    ),
    (
        "808080808080808080808080808080808080808080808080",
        "letter advice cage absurd amount doctor acoustic avoid letter advice cage absurd amount doctor acoustic avoid letter always",
    ),
    (
        "ffffffffffffffffffffffffffffffffffffffffffffffff",
        "zoo zoo zoo zoo zoo zoo zoo zoo zoo zoo zoo zoo zoo zoo zoo zoo zoo when",
    ),
];

#[test]
fn bip39_known_vectors() {
    for (e, phrase_text) in KNOWN {
        let entropy: [u8; ENTROPY_LEN] = h(e).try_into().unwrap();
        let words = phrase::encode(&entropy);
        assert_eq!(words.join(" "), *phrase_text);
        let parsed: Vec<&str> = phrase_text.split(' ').collect();
        assert_eq!(&phrase::decode(&parsed).unwrap()[..], &entropy[..]);
    }
}

#[test]
fn phrase_round_trip_and_normalization() {
    let mut r = ChaCha20Rng::seed_from_u64(0x7068);
    for _ in 0..200 {
        let mut e = [0u8; ENTROPY_LEN];
        r.fill_bytes(&mut e);
        let words = phrase::encode(&e);
        assert_eq!(words.len(), PHRASE_WORDS);
        assert_eq!(&phrase::decode(&words).unwrap()[..], &e[..]);
        // Upper case and surrounding whitespace denote the same phrase
        let messy: Vec<String> = words.iter().map(|w| format!("  {}\t", w.to_uppercase())).collect();
        assert_eq!(&phrase::decode(&messy).unwrap()[..], &e[..]);
    }
}

/// Replace the last word with other list words and return the first variant whose checksum fails
fn checksum_breaker(words: &[String]) -> Vec<String> {
    let mut bad = words.to_vec();
    for cand in bip39_en::WORDS {
        bad[PHRASE_WORDS - 1] = cand.to_string();
        if phrase::decode(&bad).is_err() {
            return bad;
        }
    }
    unreachable!()
}

#[test]
fn bad_phrases_are_rejected() {
    let words = phrase::encode(&[0x5a; ENTROPY_LEN]);
    // Bad checksum (every word is in the list)
    let bad = checksum_breaker(&words);
    assert!(bad.iter().all(|w| bip39_en::WORDS.contains(&w.as_str())));
    assert_eq!(phrase::decode(&bad).unwrap_err(), Error::BadPhrase);
    // Word not in the list
    let mut typo = words.to_vec();
    typo[3] = "abandn".into();
    assert_eq!(phrase::decode(&typo).unwrap_err(), Error::BadPhrase);
    // Word count: a standard 12-word (128-bit) phrase is rejected too
    let twelve = ["abandon"; 11].iter().chain(&["about"]).copied().collect::<Vec<_>>();
    assert_eq!(phrase::decode(&twelve).unwrap_err(), Error::BadPhrase);
    assert_eq!(phrase::decode(&words[..17]).unwrap_err(), Error::BadPhrase);
    let mut more = words.to_vec();
    more.push("abandon".into());
    assert_eq!(phrase::decode(&more).unwrap_err(), Error::BadPhrase);
    assert_eq!(phrase::decode::<&str>(&[]).unwrap_err(), Error::BadPhrase);
    // So is a standard 24-word phrase
    let twenty_four = ["abandon"; 23].iter().chain(&["art"]).copied().collect::<Vec<_>>();
    assert_eq!(phrase::decode(&twenty_four).unwrap_err(), Error::BadPhrase);
    // Whitespace inside a single word
    let mut joined = words.to_vec();
    joined[0] = format!("{} {}", words[0], words[1]);
    assert_eq!(phrase::decode(&joined).unwrap_err(), Error::BadPhrase);
    assert_eq!(Core::recovery_locator(&bad).unwrap_err(), Error::BadPhrase);
}

// ── Prepare and recover ──

#[test]
fn self_recovery_round_trip() {
    let (account, enc) = keys(1);
    let mut old = with_keys(seeded(2), &account, &enc);
    let acc_pub = old.public_key(Slot::Account).unwrap();
    let enc_pub = old.public_key(Slot::Enc).unwrap();
    let kit = old.prepare_self_recovery().unwrap();
    assert_eq!(kit.words.len(), PHRASE_WORDS);
    assert_eq!(kit.backup.len(), BACKUP_LEN);
    assert_eq!(kit.backup[0], BACKUP_V4);
    assert_eq!(BACKUP_V4, 4);
    assert_eq!(kit.locator.len(), LOCATOR_LEN);
    assert_eq!(Core::recovery_locator(&kit.words).unwrap(), kit.locator);
    // The locator depends on the phrase alone: it is independent of U and differs from S
    let r = phrase::decode(&kit.words).unwrap();
    let mut ikm = r.to_vec();
    ikm.extend_from_slice(&kit.server_share[..]);
    let s = crypto::hkdf32(&ikm, None, crypto::SELF_RECOVERY_INFO);
    assert_ne!(&s[..], &kit.locator[..]);
    assert_eq!(&crypto::hkdf32(&r[..], None, crypto::RECOVERY_LOCATOR_INFO)[..], &kit.locator[..]);

    // New phone with no keys at all
    let mut fresh = seeded(3);
    let pubs = fresh.complete_self_recovery(&kit.words, &kit.backup, &kit.server_share[..], &acc_pub).unwrap();
    assert_eq!(pubs, (acc_pub, enc_pub));
    assert_eq!(fresh.slot_secret(Slot::Account).as_deref(), Some(&account));
    assert_eq!(fresh.slot_secret(Slot::Enc).as_deref(), Some(&enc));
    assert!(!fresh.has(Slot::Recovery) && !fresh.has(Slot::Device));
    // Repeating on a device that already holds the same keys succeeds (e.g. after the wrapper stored one key and stopped)
    assert_eq!(fresh.complete_self_recovery(&kit.words, &kit.backup, &kit.server_share[..], &acc_pub).unwrap(), pubs);
    // Both seeds regenerate the same X25519, ML-KEM, Ed25519 and ML-DSA keys, so the server's HEK and ML-DSA records
    // need not be rewritten
    assert_eq!(fresh.encryption_hybrid_key().unwrap(), old.encryption_hybrid_key().unwrap());
    assert_eq!(fresh.sign_encryption_key_v3().unwrap(), old.sign_encryption_key_v3().unwrap());
    let (b_old, b_new) = (old.pq_sig_binding().unwrap(), fresh.pq_sig_binding().unwrap());
    assert_eq!((b_new.pk_d, b_new.dh, b_new.ds), (b_old.pk_d, b_old.dh, b_old.ds));
    assert!(Core::verify_pq_sig_binding(&acc_pub, &b_new.pk_d, &b_new.dh, &b_new.ds, &b_new.dq));
    // The recovered device opens an outer envelope sealed by the old device
    let h = old.create_content_key();
    let env = old.seal_outer(&h, gori_core::core::OuterPurpose::Keep, &old.encryption_hybrid_key().unwrap()).unwrap();
    assert!(fresh.open_outer(gori_core::core::OuterPurpose::Keep, &env).is_ok());

    // Input with mixed case and extra whitespace
    let messy: Vec<String> = kit.words.iter().map(|w| format!(" {} ", w.to_uppercase())).collect();
    let mut fresh = seeded(4);
    assert_eq!(fresh.complete_self_recovery(&messy, &kit.backup, &kit.server_share[..], &acc_pub).unwrap(), pubs);

    // Preparing again yields a new phrase, U and locator
    let kit2 = old.prepare_self_recovery().unwrap();
    assert_ne!(kit2.words, kit.words);
    assert_ne!(&kit2.server_share[..], &kit.server_share[..]);
    assert_ne!(kit2.locator, kit.locator);
    // The old phrase does not open the new backup
    assert_eq!(
        seeded(5).complete_self_recovery(&kit.words, &kit2.backup, &kit2.server_share[..], &acc_pub).unwrap_err(),
        Error::RecoveryFailed
    );
}

#[test]
fn prepare_needs_account_and_encryption_keys() {
    let (account, enc) = keys(10);
    assert_eq!(seeded(1).prepare_self_recovery().err(), Some(Error::NothingToRecover));
    let mut only_account = seeded(1);
    only_account.load(Slot::Account, &account).unwrap();
    assert_eq!(only_account.prepare_self_recovery().err(), Some(Error::NothingToRecover));
    let mut only_enc = seeded(1);
    only_enc.load(Slot::Enc, &enc).unwrap();
    assert_eq!(only_enc.prepare_self_recovery().err(), Some(Error::NothingToRecover));
}

#[test]
fn complete_rejects_wrong_inputs_without_touching_slots() {
    let (account, enc) = keys(20);
    let mut old = with_keys(seeded(21), &account, &enc);
    let acc_pub = old.public_key(Slot::Account).unwrap();
    let kit = old.prepare_self_recovery().unwrap();
    let u = &kit.server_share[..];
    let empty = |c: &Core| !c.has(Slot::Account) && !c.has(Slot::Enc);

    // Wrong U: does not open (and does not say what was wrong)
    let mut c = seeded(22);
    let mut wrong_u = kit.server_share.to_vec();
    wrong_u[0] ^= 1;
    assert_eq!(c.complete_self_recovery(&kit.words, &kit.backup, &wrong_u, &acc_pub).unwrap_err(), Error::RecoveryFailed);
    assert_eq!(c.complete_self_recovery(&kit.words, &kit.backup, &[0u8; 32], &acc_pub).unwrap_err(), Error::RecoveryFailed);
    assert_eq!(c.complete_self_recovery(&kit.words, &kit.backup, &u[..31], &acc_pub).unwrap_err(), Error::InvalidArgument);
    // Bad checksum, unknown word
    let bad = checksum_breaker(&kit.words);
    assert_eq!(c.complete_self_recovery(&bad, &kit.backup, u, &acc_pub).unwrap_err(), Error::BadPhrase);
    let mut typo = kit.words.to_vec();
    typo[0] = "zzzz".into();
    assert_eq!(c.complete_self_recovery(&typo, &kit.backup, u, &acc_pub).unwrap_err(), Error::BadPhrase);
    // A different well-formed phrase (valid checksum): does not open
    let other = phrase::encode(&[0x11; ENTROPY_LEN]);
    assert_eq!(c.complete_self_recovery(&other, &kit.backup, u, &acc_pub).unwrap_err(), Error::RecoveryFailed);
    // Tampered backup
    let mut tampered = kit.backup.clone();
    tampered[60] ^= 1;
    assert_eq!(c.complete_self_recovery(&kit.words, &tampered, u, &acc_pub).unwrap_err(), Error::RecoveryFailed);
    assert!(empty(&c));

    // Another account's public key gives AccountMismatch; a public key that fails strict parsing gives InvalidArgument
    let other_acc = gori_core::crypto::ed25519_public(&[9u8; 32]);
    assert_eq!(c.complete_self_recovery(&kit.words, &kit.backup, u, &other_acc).unwrap_err(), Error::AccountMismatch);
    let mut identity = [0u8; 32];
    identity[0] = 1;
    assert_eq!(c.complete_self_recovery(&kit.words, &kit.backup, u, &identity).unwrap_err(), Error::InvalidArgument);
    assert_eq!(c.complete_self_recovery(&kit.words, &kit.backup, u, &acc_pub[..31]).unwrap_err(), Error::InvalidArgument);
    assert!(empty(&c));

    // Device that already holds different keys: KeyConflict, nothing is changed
    let (other_account, other_enc) = keys(23);
    for (slot, secret) in [(Slot::Account, other_account), (Slot::Enc, other_enc)] {
        let mut busy = seeded(24);
        busy.load(slot, &secret).unwrap();
        assert_eq!(busy.complete_self_recovery(&kit.words, &kit.backup, u, &acc_pub).unwrap_err(), Error::KeyConflict);
        assert_eq!(busy.slot_secret(slot).as_deref(), Some(&secret));
        let other_slot = if slot == Slot::Account { Slot::Enc } else { Slot::Account };
        assert!(!busy.has(other_slot), "the other slot is not filled either");
    }
}

/// Backup version byte: the phrase path accepts only version 4 (version 3 is the old format, `StaleKey`); the guardian
/// path (v1) accepts only v1
#[test]
fn backup_version_byte_selects_the_path() {
    let (account, enc) = keys(30);
    let mut old = with_keys(seeded(31), &account, &enc);
    let acc_pub = old.public_key(Slot::Account).unwrap();
    let kit = old.prepare_self_recovery().unwrap();
    let u = &kit.server_share[..];

    for v in [0u8, BACKUP_V1, 2, 5, 0xff] {
        let mut b = kit.backup.clone();
        b[0] = v;
        assert_eq!(seeded(32).complete_self_recovery(&kit.words, &b, u, &acc_pub).unwrap_err(), Error::BadBackup, "version {v}");
    }
    // Version 3 (before post-quantum: the two secrets are not seeds) is rejected explicitly as the old format
    let mut b3 = kit.backup.clone();
    b3[0] = BACKUP_V3;
    assert_eq!(seeded(32).complete_self_recovery(&kit.words, &b3, u, &acc_pub).unwrap_err(), Error::StaleKey);
    assert_eq!(
        seeded(32).complete_self_recovery(&kit.words, &kit.backup[..BACKUP_LEN - 1], u, &acc_pub).unwrap_err(),
        Error::BadBackup
    );
    let mut long = kit.backup.clone();
    long.push(0);
    assert_eq!(seeded(32).complete_self_recovery(&kit.words, &long, u, &acc_pub).unwrap_err(), Error::BadBackup);
    assert_eq!(seeded(32).complete_self_recovery(&kit.words, &[], u, &acc_pub).unwrap_err(), Error::BadBackup);

    // A guardian-path v1 backup is not opened by the v3 path
    let mut guardians: Vec<Core> = (0..2).map(|i| seeded(40 + i)).collect();
    let gp: Vec<[u8; 32]> = guardians.iter_mut().map(|g| g.generate(Slot::Enc)).collect();
    let v1 = old.prepare_recovery(&gp, 2).unwrap();
    assert_eq!(v1.backup[0], BACKUP_V1);
    assert_eq!(
        seeded(33).complete_self_recovery(&kit.words, &v1.backup, &v1.server_share[..], &acc_pub).unwrap_err(),
        Error::BadBackup
    );
    // The guardian path (complete_recovery) does not accept a phrase-path backup either
    let mut fresh = seeded(34);
    let (tmp, _) = fresh.begin_recovery();
    let resealed: Vec<Vec<u8>> =
        (0..2).map(|i| guardians[i].reseal_share(&v1.guardian_shares[i], &tmp).unwrap()).collect();
    assert_eq!(fresh.complete_recovery(&kit.backup, &resealed, u, &acc_pub).unwrap_err(), Error::BadBackup);
    // The Recovery slot is untouched after completion: v3 neither reads nor clears it
    fresh.complete_self_recovery(&kit.words, &kit.backup, u, &acc_pub).unwrap();
    assert!(fresh.has(Slot::Recovery));
}

/// A version 3 backup made by an older build (two plain secrets sealed without aad) yields `StaleKey` even with the
/// correct phrase and U; it is never read as seeds, which would produce different keys.
/// Relabeling it as version 4 does not open it either (the version byte is the aad).
#[test]
fn stale_v3_backup_is_rejected_not_reinterpreted() {
    let (account, enc) = keys(60);
    let mut new = with_keys(seeded(61), &account, &enc);
    let acc_pub = new.public_key(Slot::Account).unwrap();
    let kit = new.prepare_self_recovery().unwrap();
    let r = phrase::decode(&kit.words).unwrap();
    let mut ikm = r.to_vec();
    ikm.extend_from_slice(&kit.server_share[..]);
    let s = crypto::hkdf32(&ikm, None, crypto::SELF_RECOVERY_INFO);
    let nonce = [7u8; NONCE_LEN];
    let mut keys64 = account.to_vec();
    keys64.extend_from_slice(&enc);
    let mut old = vec![BACKUP_V3];
    old.extend_from_slice(&nonce);
    old.extend_from_slice(&crypto::seal(&s, &nonce, &[], &keys64));
    assert_eq!(old.len(), BACKUP_LEN);
    let mut c = seeded(62);
    assert_eq!(c.complete_self_recovery(&kit.words, &old, &kit.server_share[..], &acc_pub).unwrap_err(), Error::StaleKey);
    let mut relabeled = old.clone();
    relabeled[0] = BACKUP_V4;
    assert_eq!(
        c.complete_self_recovery(&kit.words, &relabeled, &kit.server_share[..], &acc_pub).unwrap_err(),
        Error::RecoveryFailed
    );
    assert!(!c.has(Slot::Account) && !c.has(Slot::Enc));
}

// ── Cross-implementation vectors ──

#[derive(Serialize, Deserialize, Debug, PartialEq, Clone)]
#[serde(rename_all = "camelCase")]
struct Case {
    /// Account identity seed and encryption seed (fixed test values; these are seeds since the post-quantum version)
    account: String,
    enc: String,
    account_pub: String,
    enc_pub: String,
    /// Randomness drawn by prepare, in order: R(24), U(32), nonce(24)
    entropy: String,
    server_share: String,
    nonce: String,
    words: Vec<String>,
    backup: String,
    locator: String,
}

#[derive(Serialize, Deserialize, Debug, PartialEq, Clone)]
struct Fixture {
    generator: String,
    cases: Vec<Case>,
}

fn dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/vectors")
}

fn generate() -> Fixture {
    let cases = (0..3u64)
        .map(|i| {
            let (account, enc) = keys(0x7365_6c66 + i);
            let mut c = with_keys(seeded(0x7633 + i), &account, &enc);
            let kit = c.prepare_self_recovery().unwrap();
            Case {
                account: x(&account),
                enc: x(&enc),
                account_pub: x(&c.public_key(Slot::Account).unwrap()),
                enc_pub: x(&c.public_key(Slot::Enc).unwrap()),
                entropy: x(&phrase::decode(&kit.words).unwrap()[..]),
                server_share: x(&kit.server_share[..]),
                nonce: x(&kit.backup[1..25]),
                words: kit.words.to_vec(),
                backup: x(&kit.backup),
                locator: x(&kit.locator),
            }
        })
        .collect();
    Fixture { generator: "gori-core (Rust), self-recovery v3 backup version 4 (seed), seeds 0x73656c66+i / 0x7633+i".into(), cases }
}

/// Check one vector set fully against this core: replaying the same randomness gives byte-identical output, and it opens
fn check(f: &Fixture) {
    let who = &f.generator;
    assert!(!f.cases.is_empty());
    for (i, case) in f.cases.iter().enumerate() {
        let entropy: [u8; ENTROPY_LEN] = h(&case.entropy).try_into().unwrap();
        assert_eq!(phrase::encode(&entropy).to_vec(), case.words, "{who}#{i}: phrase");
        assert_eq!(&phrase::decode(&case.words).unwrap()[..], &entropy[..], "{who}#{i}: phrase → R");
        assert_eq!(x(&Core::recovery_locator(&case.words).unwrap()), case.locator, "{who}#{i}: locator");

        // Prepare again with the same R, U and nonce: byte-identical
        let mut stream = h(&case.entropy);
        stream.extend(h(&case.server_share));
        stream.extend(h(&case.nonce));
        let mut c = with_keys(Core::with_rng(Box::new(Replay(stream))), &h(&case.account), &h(&case.enc));
        assert_eq!(x(&c.public_key(Slot::Account).unwrap()), case.account_pub);
        assert_eq!(x(&c.public_key(Slot::Enc).unwrap()), case.enc_pub);
        let kit = c.prepare_self_recovery().unwrap();
        assert_eq!(kit.words.to_vec(), case.words, "{who}#{i}: re-prepared phrase");
        assert_eq!(x(&kit.backup), case.backup, "{who}#{i}: re-prepared backup");
        assert_eq!(x(&kit.server_share[..]), case.server_share);
        assert_eq!(x(&kit.locator), case.locator);

        // Open on a new phone
        let mut fresh = seeded(900 + i as u64);
        let (a, e) = fresh
            .complete_self_recovery(&case.words, &h(&case.backup), &h(&case.server_share), &h(&case.account_pub))
            .unwrap_or_else(|err| panic!("{who}#{i}: recovery: {err}"));
        assert_eq!((x(&a), x(&e)), (case.account_pub.clone(), case.enc_pub.clone()));
        assert_eq!(x(fresh.slot_secret(Slot::Account).unwrap().as_ref()), case.account);
        assert_eq!(x(fresh.slot_secret(Slot::Enc).unwrap().as_ref()), case.enc);
        let mut wrong_u = h(&case.server_share);
        wrong_u[31] ^= 0x80;
        assert_eq!(
            seeded(1).complete_self_recovery(&case.words, &h(&case.backup), &wrong_u, &h(&case.account_pub)).unwrap_err(),
            Error::RecoveryFailed,
            "{who}#{i}: wrong U"
        );
    }
}

fn read(name: &str) -> Fixture {
    let p = dir().join(name);
    let s = std::fs::read_to_string(&p).unwrap_or_else(|_| panic!("vector file not found: {}", p.display()));
    serde_json::from_str(&s).unwrap()
}

#[test]
fn rust_vectors_are_reproducible_and_self_consistent() {
    let f = generate();
    check(&f);
    let path = dir().join("self-recovery-rust.json");
    if std::env::var("GORI_WRITE_VECTORS").as_deref() == Ok("1") {
        std::fs::write(&path, serde_json::to_string_pretty(&f).unwrap() + "\n").unwrap();
    }
    assert_eq!(read("self-recovery-rust.json"), f, "self-recovery-rust.json differs from the generator; regenerate it with GORI_WRITE_VECTORS=1");
}

#[test]
fn dev_core_vectors_open_in_rust() {
    let f = read("self-recovery-dev.json");
    assert!(f.generator.contains("JavaScript reference implementation"), "{}", f.generator);
    check(&f);
}

// ── C boundary ──

fn take(buf: GoriBuf) -> Vec<u8> {
    let v = if buf.ptr.is_null() { Vec::new() } else { unsafe { std::slice::from_raw_parts(buf.ptr, buf.len) }.to_vec() };
    unsafe { ffi::gori_buf_free(buf) };
    v
}

#[test]
fn ffi_round_trip() {
    let (account, enc) = keys(50);
    unsafe {
        let old = ffi::gori_core_new();
        assert_eq!(ffi::gori_load_vault(old, c"account-seed-v2".as_ptr(), account.as_ptr(), 32, std::ptr::null_mut()), 0);
        assert_eq!(ffi::gori_load_vault(old, c"enc-seed-v2".as_ptr(), enc.as_ptr(), 32, std::ptr::null_mut()), 0);
        let mut acc_pub = [0u8; 32];
        assert_eq!(ffi::gori_public_key(old, Slot::Account as u32, acc_pub.as_mut_ptr()), 0);

        let (mut p, mut b) = (GoriBuf { ptr: std::ptr::null_mut(), len: 0 }, GoriBuf { ptr: std::ptr::null_mut(), len: 0 });
        let (mut u, mut l) = ([0u8; 32], [0u8; 32]);
        // A NULL output pointer: nothing is done
        assert_eq!(
            ffi::gori_prepare_self_recovery(old, &mut p, std::ptr::null_mut(), u.as_mut_ptr(), l.as_mut_ptr()),
            Error::InvalidArgument as i32
        );
        assert_eq!(ffi::gori_prepare_self_recovery(old, &mut p, &mut b, u.as_mut_ptr(), l.as_mut_ptr()), 0);
        let phrase_bytes = take(p);
        let backup = take(b);
        let text = std::str::from_utf8(&phrase_bytes).unwrap();
        let words: Vec<&str> = text.split(' ').collect();
        assert_eq!(words.len(), PHRASE_WORDS, "words are joined by single spaces: {text:?}");
        assert!(words.iter().all(|w| bip39_en::WORDS.contains(w)));
        assert_eq!((backup.len(), backup[0]), (BACKUP_LEN, BACKUP_V4));
        assert_eq!(Core::recovery_locator(&words).unwrap(), l);

        // Locator: repeated whitespace and upper case give the same result
        let messy = format!("  {}  \n", text.to_uppercase().replace(' ', "\t  "));
        let mut l2 = [0u8; 32];
        assert_eq!(ffi::gori_recovery_locator(messy.as_ptr(), messy.len(), l2.as_mut_ptr()), 0);
        assert_eq!(l2, l);
        let not_utf8 = [0xffu8, 0xfe, 0x20];
        assert_eq!(ffi::gori_recovery_locator(not_utf8.as_ptr(), 3, l2.as_mut_ptr()), Error::BadPhrase as i32);
        let huge = vec![b' '; 4096];
        assert_eq!(ffi::gori_recovery_locator(huge.as_ptr(), huge.len(), l2.as_mut_ptr()), Error::BadPhrase as i32);
        assert_eq!(ffi::gori_recovery_locator(phrase_bytes.as_ptr(), phrase_bytes.len(), std::ptr::null_mut()), Error::InvalidArgument as i32);

        let fresh = ffi::gori_core_new();
        let (mut a, mut e) = ([0u8; 32], [0u8; 32]);
        let complete = |phrase: &[u8], out_a: *mut u8, out_e: *mut u8| {
            ffi::gori_complete_self_recovery(
                fresh,
                phrase.as_ptr(),
                phrase.len(),
                backup.as_ptr(),
                backup.len(),
                u.as_ptr(),
                32,
                acc_pub.as_ptr(),
                32,
                out_a,
                out_e,
            )
        };
        // A NULL output leaves the slots empty
        assert_eq!(complete(&phrase_bytes, a.as_mut_ptr(), std::ptr::null_mut()), Error::InvalidArgument as i32);
        let mut has = 1u8;
        assert_eq!(ffi::gori_has(fresh, Slot::Account as u32, &mut has), 0);
        assert_eq!(has, 0);
        assert_eq!(complete(&not_utf8, a.as_mut_ptr(), e.as_mut_ptr()), Error::BadPhrase as i32);
        assert_eq!(complete(messy.as_bytes(), a.as_mut_ptr(), e.as_mut_ptr()), 0);
        assert_eq!(a, acc_pub);
        assert_eq!(e, Slot::Enc.public_from(&enc));
        let mut got = [0u8; 32];
        assert_eq!(ffi::gori_slot_secret(fresh, Slot::Account as u32, got.as_mut_ptr()), 0);
        assert_eq!(got, account);
        assert!(!ffi::gori_error_message(Error::BadPhrase as i32).is_null());
        ffi::gori_core_free(fresh);
        ffi::gori_core_free(old);
    }
}
